package com.cq.maintenance.repair;

import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
import com.cq.maintenance.common.exception.BusinessException;import com.cq.maintenance.equipment.entity.*;import com.cq.maintenance.equipment.service.EquipmentStateService;import com.cq.maintenance.repair.dto.RepairRequestCreateRequest;import com.cq.maintenance.repair.entity.*;import com.cq.maintenance.repair.service.RepairRequestService;import com.cq.maintenance.security.LoginUser;import com.cq.maintenance.sla.service.SlaService;import com.cq.maintenance.workorder.entity.WorkOrder;import com.cq.maintenance.workorder.mapper.WorkOrderMapper;import com.cq.maintenance.workorder.service.*;import java.util.List;import org.junit.jupiter.api.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;

class RepairRequestServiceTest {
    WorkOrderMapper mapper;EquipmentStateService equipmentStates;WorkOrderStateService states;BusinessNumberService numbers;RepairRequestService service;SlaService sla;
    @BeforeEach void setUp(){mapper=mock(WorkOrderMapper.class);equipmentStates=mock(EquipmentStateService.class);states=mock(WorkOrderStateService.class);numbers=mock(BusinessNumberService.class);sla=mock(SlaService.class);service=new RepairRequestService(mapper,mock(WorkOrderScopeService.class),numbers,equipmentStates,states,mock(WorkOrderService.class),sla);when(numbers.next("RR")).thenReturn("RR1");when(numbers.next("WO")).thenReturn("WO1");doAnswer(i->{((RepairRequest)i.getArgument(0)).setId(10L);return 1;}).when(mapper).insertRepairRequest(any());doAnswer(i->{((WorkOrder)i.getArgument(0)).setId(20L);return 1;}).when(mapper).insertWorkOrder(any());when(mapper.markRepairConverted(10L)).thenReturn(1);login("REPORTER");}
    @AfterEach void clear(){SecurityContextHolder.clearContext();}
    void login(String role){LoginUser u=new LoginUser(5L,"reporter","报修人","ENABLED",List.of(role),List.of(),List.of(),null,List.of());SecurityContextHolder.getContext().setAuthentication(UsernamePasswordAuthenticationToken.authenticated(u,null,List.of()));}
    Equipment equipment(EquipmentStatus status){Equipment e=new Equipment();e.setId(3L);e.setStatus(status);when(mapper.lockEquipment(3L)).thenReturn(e);return e;}
    RepairRequestCreateRequest input(RepairSource source){return new RepairRequestCreateRequest(3L,RepairPriority.IMPORTANT,"异常振动",source);}
    @Test void runningEquipmentCreatesRepairAndWorkOrder(){equipment(EquipmentStatus.RUNNING);var result=service.create(input(RepairSource.PC));assertEquals(20L,result.workOrderId());verify(sla).bindRepairOrder(20L,RepairPriority.IMPORTANT);verify(equipmentStates).transition(eq(3L),eq(EquipmentStatus.FAULT),contains("RR1"),eq("WORK_ORDER"),eq(20L),eq(5L));verify(states).created(any(),eq(5L));}
    @Test void invalidEquipmentIsRejected(){when(mapper.lockEquipment(3L)).thenReturn(null);assertThrows(BusinessException.class,()->service.create(input(RepairSource.PC)));}
    @Test void scrappedEquipmentIsRejected(){equipment(EquipmentStatus.SCRAPPED);assertThrows(BusinessException.class,()->service.create(input(RepairSource.PC)));}
    @Test void faultEquipmentIsRejected(){equipment(EquipmentStatus.FAULT);assertThrows(BusinessException.class,()->service.create(input(RepairSource.PC)));}
    @Test void duplicateActiveOrderIsRejected(){equipment(EquipmentStatus.RUNNING);when(mapper.countActiveRepairOrders(3L,null)).thenReturn(1L);assertThrows(BusinessException.class,()->service.create(input(RepairSource.PC)));}
    @Test void reporterCannotPretendEngineerSource(){equipment(EquipmentStatus.RUNNING);assertThrows(BusinessException.class,()->service.create(input(RepairSource.ENGINEER)));}
    @Test void reporterIdAlwaysComesFromLogin(){equipment(EquipmentStatus.RUNNING);service.create(input(RepairSource.PC));verify(mapper).insertRepairRequest(argThat(r->r.getReporterId().equals(5L)));}
}
